function groupAnagrams(strs) {
    const d = new Map();
    for (const s of strs) {
        const k = s.split('').sort().join('');
        if (!d.has(k)) {
            d.set(k, []);
        }
        d.get(k).push(s);
    }
    return Array.from(d.values());
}

